<template><div class="app-container"><el-form :inline="true" size="small" :model="query"><el-form-item label="品牌名称"><el-input v-model="query.brandName" clearable @keyup.enter.native="load"/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option label="正常" value="0"/><el-option label="停用" value="1"/></el-select></el-form-item><el-form-item><el-button type="primary" icon="el-icon-search" size="mini" @click="load">查询</el-button></el-form-item></el-form><el-row class="mb8"><el-button type="primary" plain icon="el-icon-plus" size="mini" @click="openAdd" v-hasPermi="['mall:brand:add']">新增</el-button><right-toolbar :showSearch.sync="showSearch" @queryTable="load"/></el-row><el-table v-loading="loading" :data="list"><el-table-column prop="brandId" label="编号" width="80"/><el-table-column prop="brandName" label="品牌名称"/><el-table-column prop="logoUrl" label="Logo" show-overflow-tooltip/><el-table-column prop="description" label="描述" show-overflow-tooltip/><el-table-column prop="sortNo" label="排序" width="70"/><el-table-column label="状态" width="90"><template slot-scope="s"><el-tag :type="s.row.status === '0' ? 'success' : 'info'">{{ s.row.status === '0' ? '正常' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template slot-scope="s"><el-button type="text" size="mini" @click="openEdit(s.row)" v-hasPermi="['mall:brand:edit']">修改</el-button><el-button type="text" size="mini" @click="remove(s.row)" v-hasPermi="['mall:brand:remove']">删除</el-button></template></el-table-column></el-table><el-dialog :title="title" :visible.sync="dialog" width="500px"><el-form :model="form" label-width="90px"><el-form-item label="品牌名称" required><el-input v-model="form.brandName"/></el-form-item><el-form-item label="Logo 地址"><el-input v-model="form.logoUrl"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortNo" :min="0"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio label="0">正常</el-radio><el-radio label="1">停用</el-radio></el-radio-group></el-form-item></el-form><div slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">确定</el-button></div></el-dialog></div></template>
<script>import { listBrands, addBrand, updateBrand, delBrand } from '@/api/mall/catalog'
export default { name: 'MallBrand', data () { return { showSearch: true, loading: false, list: [], query: {}, dialog: false, title: '', form: {} } }, created () { this.load() }, methods: { load () { this.loading = true; listBrands(this.query).then(r => { this.list = r.data || [] }).finally(() => { this.loading = false }) }, openAdd () { this.title = '新增品牌'; this.form = { status: '0', sortNo: 0 }; this.dialog = true }, openEdit (r) { this.title = '修改品牌'; this.form = Object.assign({}, r); this.dialog = true }, save () { if (!this.form.brandName) return this.$modal.msgError('请输入品牌名称'); (this.form.brandId ? updateBrand : addBrand)(this.form).then(() => { this.$modal.msgSuccess('保存成功'); this.dialog = false; this.load() }) }, remove (r) { this.$modal.confirm('确认删除该品牌？').then(() => delBrand(r.brandId)).then(() => { this.load(); this.$modal.msgSuccess('删除成功') }).catch(() => {}) } } }</script>
